def create_payment(idempotency_key, amount, account_id):
    existing = db.query(
        "SELECT * FROM payments WHERE idempotency_key = %s", idempotency_key
    )
    if existing:
        return existing

    payment = psp.charge(account_id, amount)   # external call
    db.insert("payments", {
        "idempotency_key": idempotency_key,
        "psp_ref": payment.ref,
        "amount": amount,
    })
    return payment

func Merge(local, incoming Record) Record {
    if incoming.UpdatedAt.After(local.UpdatedAt) {
        return incoming
    }
    return local
